// Decides which reminder (if any) each open invoice should get today.
// A row gets at most one message per run, and never the same stage twice.
const s = $('Set reminder settings').first().json;
const reminderDays = String(s.reminder_days).split(',').map(d => Number(d.trim())).filter(d => !Number.isNaN(d)).sort((a, b) => a - b);
const escalationDay = Number(s.escalation_day);
const closed = String(s.closed_statuses).split(',').map(x => x.trim().toLowerCase());

const DAY = 86400000;
// Sheets returns real dates as serial numbers (days since 1899-12-30); text dates must be YYYY-MM-DD
const toDate = v => typeof v === 'number' ? new Date(Date.UTC(1899, 11, 30) + v * DAY) : new Date(String(v).trim().slice(0, 10) + 'T00:00:00Z');
const isoDay = v => { const d = toDate(v); return Number.isNaN(d.getTime()) ? String(v) : d.toISOString().slice(0, 10); };
const today = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');

const tones = [
  { label: 'friendly', subject: 'Friendly reminder: invoice {id} is due', intro: 'This is a quick reminder that the invoice below is due. If it has already been paid, please ignore this message.' },
  { label: 'helpful', subject: 'Invoice {id} is {days} days overdue', intro: 'We have not yet received payment for the invoice below.' },
  { label: 'firm', subject: 'Action needed: invoice {id} is {days} days overdue', intro: 'The invoice below is now {days} days past due. Please arrange payment or let us know the expected payment date by replying to this email.' },
];

const results = [];
for (const item of $input.all()) {
  const r = item.json;
  const status = String(r.status || '').trim().toLowerCase();
  if (closed.includes(status)) continue;
  if (!r.invoice_id || !r.due_date) continue;

  const due = toDate(r.due_date);
  if (Number.isNaN(due.getTime())) continue;
  const days = Math.round((today - due) / DAY);

  const last = r.last_stage_sent === '' || r.last_stage_sent === undefined || r.last_stage_sent === null ? -Infinity : Number(r.last_stage_sent);

  // Human hand-off wins once the escalation day is reached
  if (days >= escalationDay && last < escalationDay) {
    results.push({ json: {
      action: 'escalate', stage_day: escalationDay, days_overdue: days,
      invoice_id: r.invoice_id, customer_name: r.customer_name, customer_email: r.customer_email,
      amount: r.amount, currency: r.currency, due_date: isoDay(r.due_date),
      subject: 'Escalation: ' + r.customer_name + ' / invoice ' + r.invoice_id + ' is ' + days + ' days overdue',
      body: [
        'Automatic reminders for this invoice have ended. It now needs a personal call.',
        '',
        'Customer: ' + r.customer_name + ' <' + r.customer_email + '>',
        'Invoice: ' + r.invoice_id,
        'Amount: ' + r.amount + ' ' + (r.currency || ''),
        'Due date: ' + isoDay(r.due_date) + ' (' + days + ' days overdue)',
        'Last reminder stage sent: ' + (Number.isFinite(last) ? 'day ' + last : 'none'),
        r.notes ? 'Notes: ' + r.notes : null,
      ].filter(l => l !== null).join('\n'),
    } });
    continue;
  }

  // Highest reminder stage reached today that has not been sent yet
  const idx = reminderDays.map((d, i) => ({ d, i })).filter(x => x.d <= days && x.d > last && x.d < escalationDay).pop();
  if (!idx) continue;

  const tone = tones[Math.min(idx.i, tones.length - 1)];
  const fill = t => t.replace('{id}', r.invoice_id).replaceAll('{days}', String(days));
  const lines = [
    'Hello ' + (r.customer_name || '') + ',',
    '',
    fill(tone.intro) + (r.payment_link && idx.i > 0 ? ' You can pay directly using the link at the end of this email.' : ''),
    '',
    'Invoice: ' + r.invoice_id,
    'Amount: ' + r.amount + ' ' + (r.currency || ''),
    'Due date: ' + isoDay(r.due_date),
  ];
  if (r.payment_link) lines.push('', 'Pay online: ' + r.payment_link);
  lines.push('', 'Thank you,', s.sender_name, s.company_name);

  results.push({ json: {
    action: 'remind', stage_day: idx.d, days_overdue: days, tone: tone.label,
    invoice_id: r.invoice_id, customer_name: r.customer_name, customer_email: r.customer_email,
    amount: r.amount, currency: r.currency, due_date: isoDay(r.due_date),
    subject: fill(tone.subject), body: lines.join('\n'),
  } });
}
return results;

// Weekly aging summary: open invoices grouped by how long they are overdue.
const s = $('Set reminder settings').first().json;
if (new Date().getUTCDay() !== Number(s.aging_report_weekday)) return [];

const closed = String(s.closed_statuses).split(',').map(x => x.trim().toLowerCase());
const DAY = 86400000;
// Sheets returns real dates as serial numbers (days since 1899-12-30); text dates must be YYYY-MM-DD
const toDate = v => typeof v === 'number' ? new Date(Date.UTC(1899, 11, 30) + v * DAY) : new Date(String(v).trim().slice(0, 10) + 'T00:00:00Z');
const isoDay = v => { const d = toDate(v); return Number.isNaN(d.getTime()) ? String(v) : d.toISOString().slice(0, 10); };
const today = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
const buckets = ['Not yet due', '0-30 days', '31-60 days', '61-90 days', '90+ days'];
const totals = {};   // bucket -> currency -> amount
const counts = Object.fromEntries(buckets.map(b => [b, 0]));
const oldest = [];

for (const { json: r } of $input.all()) {
  if (closed.includes(String(r.status || '').trim().toLowerCase()) || !r.due_date) continue;
  const days = Math.round((today - toDate(r.due_date)) / DAY);
  if (Number.isNaN(days)) continue;
  const b = days < 0 ? buckets[0] : days <= 30 ? buckets[1] : days <= 60 ? buckets[2] : days <= 90 ? buckets[3] : buckets[4];
  const cur = r.currency || '';
  totals[b] = totals[b] || {};
  totals[b][cur] = (totals[b][cur] || 0) + (Number(String(r.amount).replace(',', '.')) || 0);
  counts[b]++;
  if (days > 60) oldest.push({ days, line: r.customer_name + ' / ' + r.invoice_id + ': ' + r.amount + ' ' + cur + ' (' + days + ' days)' });
}

const fmt = obj => obj ? Object.entries(obj).map(([c, v]) => v.toFixed(2) + ' ' + c).join(' + ') : '0';
const lines = ['Open receivables by age (' + today.toISOString().slice(0, 10) + ')', ''];
for (const b of buckets) lines.push(b.padEnd(12) + counts[b] + ' invoices   ' + fmt(totals[b]));
if (oldest.length) {
  lines.push('', 'Over 60 days, oldest first:');
  oldest.sort((a, b) => b.days - a.days).forEach(o => lines.push('- ' + o.line));
}
return [{ json: { subject: s.company_name + ': weekly receivables aging report', body: lines.join('\n') } }];
